#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/opportunity_execution_bridge_v17_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/profit_first_dispatcher.py "$BK/" 2>/dev/null || true
cp -a companyos/runtime/service_supervisor.py "$BK/" 2>/dev/null || true

echo "" | base64 -d > companyos/runtime/opportunity_execution_capability_bridge.py
echo "" | base64 -d > "$PREFIX/tmp/companyos_action_bridge_dispatcher_patch.py"
python "$PREFIX/tmp/companyos_action_bridge_dispatcher_patch.py"
rm -f "$PREFIX/tmp/companyos_action_bridge_dispatcher_patch.py"

echo "" | base64 -d > "$PREFIX/tmp/companyos_action_bridge_supervisor_patch.py"
python "$PREFIX/tmp/companyos_action_bridge_supervisor_patch.py"
rm -f "$PREFIX/tmp/companyos_action_bridge_supervisor_patch.py"

echo "" | base64 -d > scripts/companyos_actionbridgectl
chmod +x scripts/companyos_actionbridgectl
echo "" | base64 -d > tests/test_opportunity_execution_capability_bridge_v17.py

echo "[1/8] Compile"
python -m py_compile companyos/runtime/opportunity_execution_capability_bridge.py companyos/runtime/profit_first_dispatcher.py companyos/runtime/service_supervisor.py tests/test_opportunity_execution_capability_bridge_v17.py

echo "[2/8] Bridge tests"
python -m unittest tests.test_opportunity_execution_capability_bridge_v17 -v

echo "[3/8] Build one capability-guided action packet"
scripts/companyos_actionbridgectl once | tee .companyos_runtime/opportunity_execution_bridge_v17_first_cycle.json || true

echo "[4/8] Show action queue"
scripts/companyos_actionbridgectl queue || true

echo "[5/8] Verify dispatcher goal contains action packet contract"
python - <<'PY'
from companyos.runtime.profit_first_dispatcher import build_goal
g=build_goal()
print("DISPATCHER_CAPABILITY_PACKET_PRESENT=", "CAPABILITY-GUIDED EXECUTION PACKET" in g)
print("GOAL_LENGTH=",len(g))
PY

echo "[6/8] Commit/push"
git add companyos/runtime/opportunity_execution_capability_bridge.py companyos/runtime/profit_first_dispatcher.py companyos/runtime/service_supervisor.py scripts/companyos_actionbridgectl tests/test_opportunity_execution_capability_bridge_v17.py
git diff --cached --quiet || git commit -m "Bridge learned capabilities into guarded opportunity execution"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[7/8] Restart"
scripts/companyosctl restart || true
sleep 8

echo "[8/8] Verify"
echo "===== ACTION BRIDGE ====="
scripts/companyos_actionbridgectl status || true
echo "===== ACTION QUEUE ====="
scripts/companyos_actionbridgectl queue || true
echo "===== PROFIT DISPATCHER ====="
python - <<'PY'
from companyos.runtime.profit_first_dispatcher import maybe_dispatch
r=maybe_dispatch(min_idle_cycles=0,cooldown_seconds=0)
print(r)
PY
echo "===== SERVICES ====="
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_CAPABILITY_GUIDED_OPPORTUNITY_EXECUTION_V17=PASS"
